contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry performing the minimal sequence:
    // - ensure this test contract has enough ETH (caller funds it off-chain)
    // - call c.Deposit sending amount 'amt' from this contract
    // - read balances for this contract (msg.sender in c.Deposit) and check it increased by amt

    function runTest(uint amt) public payable {
        // Precondition: the caller provided ETH to this call so the test contract can forward it
        require(msg.value >= amt, "insufficient funding for amt");

        // observe balance before
        uint before = c.balances(address(this));

        // perform the state-changing call: Deposit must be invoked with value amt
        c.Deposit{value: amt}();

        // observe balance after
        uint after = c.balances(address(this));

        // The invariant: the recorded balance for the caller increased by exactly amt
        assert(after == before + amt);
    }

    // Allow the test contract to receive ETH so callers can fund it before calling runTest
    receive() external payable {}
}

